import{_ as d,l as i,o as e,c as s,v as o,p as n,x as r,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"饱和运算","description":"","frontmatter":{"title":"饱和运算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/saturating-arith.md","filePath":"cs/saturating-arith.md","lastUpdated":1789023840000}'),h={name:"cs/saturating-arith.md"};function A(E,a,f,_,u,m){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="饱和运算" tabindex="-1">饱和运算 <a class="header-anchor" href="#饱和运算" aria-label="Permalink to &quot;饱和运算&quot;">​</a></h1><div class="epigraph"><p>溢出时不环绕成符号相反的数，而是钉在可表示的最大或最小：音频与像素更怕「正满突然变负」，不怕少 1 个量化步。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/overflow-detect">上一课</a>给出了 <code>V</code> 与 <code>C</code>。<a href="/cs/fixed-point-dsp">定点 DSP</a> 的 MAC 截回窄宽度时，模 \\(2^n\\) 环绕会把大幅度变成错误符号。缺口是算术单元本课序的收尾：<strong>饱和</strong>——结果夹在端点，而不是绕回。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有符号饱和加：若 <code>V</code> 且结果为负，输出 \\(2^{n-1}-1\\)；若 <code>V</code> 且结果为正，输出 \\(-2^{n-1}\\)。无符号饱和：<code>C</code> 则钉在全 1 或 0（视加/减）。缺口不是新的溢出公式，而是结果 MUX：正常和 vs 两个端点常数。SIMD 指令（后课 SSE/NEON 的 <code>paddsb</code> 一类）把这套接到打包字节上；本课先钉标量/定点 MAC。</p><h3 id="饱和不是-754-的-overflow" tabindex="-1">饱和不是 754 的 overflow <a class="header-anchor" href="#饱和不是-754-的-overflow" aria-label="Permalink to &quot;饱和不是 754 的 overflow&quot;">​</a></h3><p>浮点 overflow 默认去无穷或最大有限数，并置<a href="/cs/fp-exceptions">标志</a>。整数饱和通常<strong>不</strong>产生 NaN，也常常不置 754 那五位；DSP 可能另有 sticky overflow 位。把 <code>sat add</code> 当成 <code>fadd</code>，动态范围与非数规则全错。</p><p><span class="marginnote">多媒体 ISA 把饱和写成指令语义。Harris 在 ALU 旗标之后用 MUX 夹紧。本课不把图像处理算法写进来，只交电路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加法器算出环绕和与 <code>V</code>/<code>C</code>。MUX：无溢出选和；有溢出选由符号（有符号）或操作方向（无符号减到 0）决定的端点。乘后饱和：先看宽积是否超出目标 Q 格式，再夹紧。累加器可以内部不饱和、输出时饱和，避免一串 MAC 每步都钉死——由算法选。</p>',10)),(e(),n(p,null,{default:r(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUM%5B%22%E7%8E%AF%E7%BB%95%E5%92%8C%22%5D%20--%3E%20DET%5B%22V%20%2F%20C%22%5D%0A%20%20DET%20--%3E%20MUX%5B%22%E9%80%89%E5%92%8C%E6%88%96%E7%AB%AF%E7%82%B9%22%5D%0A%20%20MUX%20--%3E%20OUT%5B%22%E9%A5%B1%E5%92%8C%E7%BB%93%E6%9E%9C%22%5D%0A%20%20OUT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AVerilog%20%E6%8F%8F%E8%BF%B0%E8%BF%99%E4%BA%9B%E9%80%9A%E8%B7%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与<a href="/cs/fp-adder">浮点加法器</a>对照：浮点用指数扩展范围；饱和定点用端点牺牲线性，换取「不过零乱跳」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>算术单元课序到此：乘除树与迭代、浮点对阶与 FMA、定点 MAC、溢出与饱和。下一单元用 HDL 描述这些块如何变成网表，而不是再发明一种算术。后课 ISA 的 SIMD 饱和指令只是把本课 MUX 铺 \\(W\\) 份。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义「无符号饱和乘」的每一种厂商变体，不讲 block floating-point 共享指数。不进入限价簿价格的定点，也不写光刻剂量控制环。</p><p>后课默认：饱和是溢出时夹紧到端点的结果 MUX；环绕仍是补码加法器的裸输出。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>V</code>/<code>C</code> 驱动端点 MUX，避免定点环绕改符号。</li><li>与 754 无穷/NaN 不是同一合同。</li><li>算术单元收尾；下一课改用 Verilog 写这些块。</li><li>出处：Harris and Harris；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const T=d(h,[["render",A]]);export{C as __pageData,T as default};
